//! Independent cross-validation against SciPy-generated reference values.
//!
//! Reference data provenance:
//!
//! * generated by `python/tests/generate_reference_values.py`
//! * uses `scipy.special.sph_harm`, `special.assoc_laguerre`, `special.gamma`
//! * committed as `docs/validation/reference-values.csv`
//! * numpy 2.0.2, scipy 1.13.1 on the generation machine
//!
//! These tests are the primary evidence that the Rust kernels agree with an
//! implementation that shares no code with them. Each test prints the maximum
//! observed deviation so that the *measured* agreement is visible, not just the
//! pass/fail verdict.

use atoms_orbitals::{radial_wavefunction, HydrogenWavefunction};
use atoms_validation::{
    rows_of_kind, EXPECTED_DENSITY_ROWS, EXPECTED_HARMONIC_ROWS, EXPECTED_RADIAL_ROWS,
};
use num_complex::Complex;

/// Tolerance for spherical harmonic agreement (absolute, values are O(1)).
const HARMONIC_ABS_TOL: f64 = 1e-13;
/// Tolerance for radial function agreement (relative).
const RADIAL_REL_TOL: f64 = 1e-12;
/// Tolerance for probability density agreement (relative).
const DENSITY_REL_TOL: f64 = 1e-11;

#[test]
fn spherical_harmonics_match_scipy() {
    let rows = rows_of_kind("harmonic");
    assert_eq!(rows.len(), EXPECTED_HARMONIC_ROWS);

    let mut worst = 0.0_f64;
    let mut worst_ctx = String::new();
    for r in &rows {
        let l = r.uint(0);
        let m = r.int(1);
        let theta = r.number(2);
        let phi = r.number(3);
        let expected = Complex::new(r.number(4), r.number(5));
        let got = atoms_orbitals::spherical_harmonics::evaluate(l, m, theta, phi);
        let dev = (got - expected).norm();
        if dev > worst {
            worst = dev;
            worst_ctx = format!("l={l} m={m} theta={theta} phi={phi}");
        }
        assert!(
            dev < HARMONIC_ABS_TOL,
            "Y_{l}^{m}({theta}, {phi}): rust={got} scipy={expected} deviation={dev}"
        );
    }
    println!(
        "max |Y_rust - Y_scipy| over {} samples: {worst:.3e} ({worst_ctx})",
        rows.len()
    );
}

#[test]
fn radial_wavefunctions_match_scipy() {
    let rows = rows_of_kind("radial");
    assert_eq!(rows.len(), EXPECTED_RADIAL_ROWS);

    let mut worst = 0.0_f64;
    let mut worst_ctx = String::new();
    for r in &rows {
        let n = r.uint(0);
        let l = r.uint(1);
        let radius = r.number(2);
        let expected = r.number(4);
        let got = radial_wavefunction(n, l, radius).expect("valid quantum numbers");
        // Relative comparison, but guard the exactly-zero case at r = 0, l > 0.
        let denom = expected.abs().max(1e-300);
        let rel = if expected == 0.0 {
            got.abs()
        } else {
            (got - expected).abs() / denom
        };
        if rel > worst {
            worst = rel;
            worst_ctx = format!("n={n} l={l} r={radius}");
        }
        assert!(
            rel < RADIAL_REL_TOL,
            "R_{n}{l}({radius}): rust={got} scipy={expected} rel={rel}"
        );
    }
    println!(
        "max relative |R_rust - R_scipy| over {} samples: {worst:.3e} ({worst_ctx})",
        rows.len()
    );
}

#[test]
fn probability_densities_match_scipy() {
    let rows = rows_of_kind("density");
    assert_eq!(rows.len(), EXPECTED_DENSITY_ROWS);

    let mut worst = 0.0_f64;
    let mut worst_ctx = String::new();
    for r in &rows {
        let n = r.uint(0);
        let l = r.uint(1);
        let m = r.int(2);
        let radius = r.number(3);
        let theta = r.number(4);
        let phi = r.number(5);
        let expected = r.number(6);
        let wf = HydrogenWavefunction::new(n, l, m).expect("valid quantum numbers");
        let got = wf.probability_density_spherical(radius, theta, phi);
        let rel = (got - expected).abs() / expected.abs().max(1e-300);
        if rel > worst {
            worst = rel;
            worst_ctx = format!("n={n} l={l} m={m} r={radius}");
        }
        assert!(
            rel < DENSITY_REL_TOL,
            "|psi_{n}{l}{m}({radius}, {theta}, {phi})|^2: rust={got} scipy={expected} rel={rel}"
        );
    }
    println!(
        "max relative |psi|^2 deviation over {} samples: {worst:.3e} ({worst_ctx})",
        rows.len()
    );
}

/// The Laguerre recurrence is the accuracy-critical inner loop of the radial
/// wavefunction. It is compared against a reference computed with **exact
/// rational arithmetic** (`fractions.Fraction`), which carries no floating-point
/// error at all, up to `k = 39` and `alpha = 61`.
#[test]
fn laguerre_recurrence_matches_exact_rational_arithmetic() {
    use atoms_numerics::special::generalized_laguerre;
    use atoms_validation::EXPECTED_LAGUERRE_ROWS;

    let rows = rows_of_kind("laguerre");
    assert_eq!(rows.len(), EXPECTED_LAGUERRE_ROWS);

    let mut worst = 0.0_f64;
    let mut worst_ctx = String::new();
    for r in &rows {
        let k = r.uint(0);
        let alpha = r.uint(1) as f64;
        let x = r.number(2);
        let expected = r.number(4);
        let got = generalized_laguerre(k, alpha, x);
        let rel = if expected == 0.0 {
            got.abs()
        } else {
            (got - expected).abs() / expected.abs()
        };
        if rel > worst {
            worst = rel;
            worst_ctx = format!("k={k} alpha={alpha} x={x}");
        }
        assert!(
            rel < 1e-13,
            "L_{k}^{alpha}({x}): rust={got:e} exact={expected:e} rel={rel:e}"
        );
    }
    println!(
        "max relative deviation from exact rational arithmetic over {} Laguerre \
         evaluations: {worst:.3e} ({worst_ctx})",
        rows.len()
    );
}

/// The reference file must not contain a single value that is independent of the
/// `l`, `m` structure: a sanity check that the parser is reading the intended
/// columns and that the file was not silently truncated to a constant.
#[test]
fn reference_data_is_not_degenerate() {
    let harmonics = rows_of_kind("harmonic");
    let distinct: std::collections::HashSet<String> = harmonics
        .iter()
        .map(|r| format!("{}{}", r.fields[4], r.fields[5]))
        .collect();
    assert!(
        distinct.len() > 50,
        "only {} distinct harmonic reference values",
        distinct.len()
    );
}
